import{z as d,x as p,o as r,c as T,q as E,j as s,D as t,d as o,s as n,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"BitTorrent 与 DHT","description":"","frontmatter":{"title":"BitTorrent 与 DHT","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bittorrent-dht.md","filePath":"cs/bittorrent-dht.md","lastUpdated":1791413859000}'),D={name:"cs/bittorrent-dht.md"};function h(A,a,B,m,C,P){const i=p("Mermaid");return r(),T("div",null,[a[2]||(a[2]=E('<h1 id="bittorrent-与-dht" tabindex="-1">BitTorrent 与 DHT <a class="header-anchor" href="#bittorrent-与-dht" aria-label="Permalink to &quot;BitTorrent 与 DHT&quot;">​</a></h1><div class="epigraph"><p>文件切成块，对等方互传；tracker 或 DHT 负责发现邻居。稀有块优先，使复制在群体里展开，而不是一台源打满 $C$。</p><footer>—— 据 Cohen, The BitTorrent Protocol；BEP 5 等 DHT 实践；Kademlia 对照整理</footer></div><p><a href="/cs/ftp-passive">FTP</a> 是中心源。<a href="/cs/ftp-passive">上一课</a> 结束该课序。缺口是 <strong>P2P 分发</strong>：swarm、片、DHT。本课不把 WebRTC 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>热门文件把 HTTP 源与 CDN 账单打满。BitTorrent：元数据列块哈希，对等互传，稀缺优先，tit-for-tat 激励上传。Tracker 集中列表；DHT（Kademlia 风格）用 infohash 找 peers，无单点。NAT 仍痛，要打洞或中继。不是多播树，是应用层覆盖。</p><p>不要把 DHT 写成 DNS。</p><p><span class="marginnote">常见误区：把 DHT 想成「去中心化的 DNS」。DNS 是分层授权的树，根区与顶级域由机构管；DHT 没有根，一个键归谁管由哈希距离决定，节点进出只挪动一小段键的负责权。两者的「查询名字找东西」只是表象相似。</span></p><p><span class="marginnote">Cohen 规范。BEP 文档。本课不写盗版场景。</span></p><h3 id="应用层-mesh" tabindex="-1">应用层 mesh <a class="header-anchor" href="#应用层-mesh" aria-label="Permalink to &quot;应用层 mesh&quot;">​</a></h3><p>块哈希防污染；DHT 去中心发现。不是 DNS，也不是 IP 多播树。NAT 与激励是部署约束。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：种子 → 块 → 邻居集合。对照 CDN：CDN 有树与缓存层次，BT 有 mesh。与 ECMP 无关直接。</p>',12)),(r(),s(l,null,{default:t(()=>[n(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20META%5B%22infohash%20%E4%B8%8E%E5%9D%97%22%5D%20--%3E%20DISC%5B%22tracker%20%E6%88%96%20DHT%22%5D%0A%20%20DISC%20--%3E%20PEER%5B%22%E5%AF%B9%E7%AD%89%E8%BF%9E%E6%8E%A5%22%5D%0A%20%20PEER%20--%3E%20RARE%5B%22%E7%A8%80%E6%9C%89%E5%9D%97%E4%BC%98%E5%85%88%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"「稀有块优先」可以类比成物种保护：最濒危的块一旦随个别节点退出而灭绝，整个 swarm 就永远凑不齐文件。先传最少的副本，等于把遗传多样性铺开——这是 P2P 自愈能力的来源，不是道德，是算术。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[o("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"传输仍是 TCP（或 μTP），拥塞各连接 AIMD，共享接入会互抢——接入 AQM 有帮助。DNS 可找 tracker。加密扩展点名。GeoDNS 不调度块。",-1)),a[6]||(a[6]=e("p",null,"安全：污染块靠哈希；DHT 污染是另一攻击面，点名不展开。",-1)),a[7]||(a[7]=e("p",null,"DHT 在没有 tracker 时如何找到 peers，值得单独画一条查找链。",-1)),(r(),s(l,null,{default:t(()=>[n(i,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E8%A6%81%E6%89%BE%20infohash%20%E7%9A%84%E8%8A%82%E7%82%B9%22%5D%20--%3E%20N1%5B%22%E9%97%AE%E8%87%AA%E5%B7%B1%E8%B7%AF%E7%94%B1%E8%A1%A8%E9%87%8C%E6%9C%80%E8%BF%91%E7%9A%84%E8%8A%82%E7%82%B9%22%5D%0A%20%20N1%20--%3E%20N2%5B%22%E5%AE%83%E4%BB%AC%E8%BF%94%E5%9B%9E%E6%9B%B4%E8%BF%91%E7%9A%84%E8%8A%82%E7%82%B9%22%5D%0A%20%20N2%20--%3E%20CONV%7B%22%E5%80%99%E9%80%89%E4%B8%8D%E5%86%8D%E6%9B%B4%E8%BF%91%EF%BC%9F%22%7D%0A%20%20CONV%20--%3E%7C%22%E5%90%A6%22%7C%20N1%0A%20%20CONV%20--%3E%7C%22%E6%98%AF%22%7C%20PEERS%5B%22%E6%8C%81%E6%9C%89%E8%AF%A5%20infohash%20%E7%9A%84%20peer%20%E5%88%97%E8%A1%A8%22%5D%0A%20%20PEERS%20--%3EConn%5B%22%E7%9B%B4%E6%8E%A5%E4%B8%8E%20peer%20%E6%8D%A2%E5%9D%97%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=E('<p><span class="marginnote">术语翻译：DHT（分布式哈希表）就是把键值对摊到所有参与者手里，每个节点负责键空间的一小段；查询不问中心，而是一跳一跳问「谁离这个键的哈希更近」。Kademlia 用 160 位异或距离度量，路由表按距离分桶存 \\(k\\)（约 8 到 20）个节点，查找通常对数跳收敛。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 BitTorrent v2 的全部。WebRTC 与 ICE 是下一课。后课默认：P2P 分发 = 块交换 + 发现；DHT 去中心发现。</p><p>企业网禁 P2P 端口是政策，不是协议缺陷。</p><p>下一课<a href="/cs/webrtc-ice">WebRTC 与 ICE</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>块交换摊源；稀有优先。</li><li>Tracker 或 DHT 发现邻居。</li><li>覆盖网在应用层，NAT 是障碍。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：Cohen；Kademlia/DHT 实践。</li></ul>',7))])}const u=d(D,[["render",h]]);export{c as __pageData,u as default};
